const DICT={};
for(const locale of LOCALES.slice(1)){const i=LOCALES.indexOf(locale);DICT[locale]={};for(const row of EXTRA_TABLE)DICT[locale][row[0]]=row[i];for(const row of TABLE)DICT[locale][row[0]]=row[i];}
let locale='pt',onChange=null;
export function getLocale(){return locale;}
export function localeTag(){return LOCALE_TAG[locale]||'pt-BR';}
export function t(str){if(locale==='pt')return str;const hit=DICT[locale]?.[norm(str)];return hit??str;}
function applyLocale(){if(typeof document!=='undefined'){document.documentElement.lang=localeTag();try{document.title=`LifeBots — ${t('Seu próximo capítulo')}`;}catch{}}}
export function setLocale(code,manual=true){if(!LOCALES.includes(code))return;locale=code;if(manual)store(LANG_KEY,code);applyLocale();onChange?.(locale);}
function navLocale(){const l=(globalThis.navigator?.language||'').toLowerCase();for(const code of['pt','es','ru','ja','en'])if(l.startsWith(code))return code;return'en';}
async function detectByIp(){
 for(const url of['https://ipwho.is/','https://api.country.is/']){
  try{
   const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),4000);
   const res=await fetch(url,{signal:ctl.signal});clearTimeout(timer);
   const data=await res.json(),cc=String(data.country_code||data.country||'').toUpperCase();
   if(cc)return countryToLocale(cc);
  }catch{}
 }
 return null;
}
function urlLocale(){try{const code=new URLSearchParams(globalThis.location?.search||'').get('lang');return LOCALES.includes(code)?code:null;}catch{return null;}}
export function initI18n(callback){
 onChange=callback||null;
 const fromUrl=urlLocale();
 if(fromUrl){locale=fromUrl;store(LANG_KEY,fromUrl);applyLocale();return;}
 const manual=read(LANG_KEY);
 if(LOCALES.includes(manual)){locale=manual;applyLocale();return;}
 const cachedGeo=read(GEO_KEY);
 locale=LOCALES.includes(cachedGeo)?cachedGeo:navLocale();
 applyLocale();
 if(typeof document==='undefined'||typeof fetch!=='function')return;
 if(globalThis.navigator?.webdriver)return;
 const host=globalThis.location?.hostname||'';
 if(!host||host==='localhost'||host==='127.0.0.1'||host.endsWith('.local'))return;
 void detectByIp().then(code=>{
  if(!code||!LOCALES.includes(code))return;
  store(GEO_KEY,code);
  if(LOCALES.includes(read(LANG_KEY)))return;
  if(code!==locale){locale=code;applyLocale();onChange?.(locale);}
 });
}
export function translateDom(root){
 if(locale==='pt'||!root)return;
 const dict=DICT[locale];if(!dict)return;
 const doc=root.nodeType===9?root:root.ownerDocument;if(!doc?.createTreeWalker)return;
 const walker=doc.createTreeWalker(root,4),nodes=[];let node;
 while(node=walker.nextNode())nodes.push(node);
 for(const text of nodes){
  if(text.parentElement?.closest('[translate="no"],script,style,textarea,code,pre'))continue;
  const value=text.nodeValue,key=norm(value);if(!key)continue;
  const hit=dict[key];if(!hit)continue;
  text.nodeValue=(value.match(/^\s*/)?.[0]||'')+hit+(value.match(/\s*$/)?.[0]||'');
 }
 const attrs=['aria-label','placeholder','title','alt'];
 const targets=root.querySelectorAll?[...root.querySelectorAll(attrs.map(a=>`[${a}]`).join(','))]:[];
 if(root.nodeType===1)targets.unshift(root);
 for(const el of targets)for(const attr of attrs){
  if(el.closest?.('[translate="no"]'))continue;
  const value=el.getAttribute?.(attr);if(!value)continue;
  const hit=dict[norm(value)];if(hit)el.setAttribute(attr,hit);
 }
}
export function resetI18n(){locale='pt';onChange=null;}
